-- 104_control_variables.sql | control de ejecucion de las variables del modelo. Compara 202507 contra 202508, donde la probabilidad media cae 1.57 pp de golpe. Una variable que se mueva ahi explica el salto. Tambien mide nulos y valores no casteables
SELECT variable,
       round(media_202507, 6)                                            AS media_202507,
       round(media_202508, 6)                                            AS media_202508,
       round(100.0 * (media_202508 / nullif(media_202507, 0) - 1), 2)    AS var_pct,
       round(nulos_pct, 4)                                               AS nulos_pct,
       round(no_numerico_pct, 4)                                         AS no_numerico_pct
FROM (
    SELECT avg(CASE WHEN p_codmes = '202507' THEN TRY_CAST(probabilidad AS DOUBLE) END) AS a0,
           avg(CASE WHEN p_codmes = '202508' THEN TRY_CAST(probabilidad AS DOUBLE) END) AS b0,
           100.0 * sum(CASE WHEN probabilidad IS NULL THEN 1 ELSE 0 END) / count(1) AS c0,
           100.0 * sum(CASE WHEN probabilidad IS NOT NULL AND TRY_CAST(probabilidad AS DOUBLE) IS NULL THEN 1 ELSE 0 END) / count(1) AS d0,
           avg(CASE WHEN p_codmes = '202507' THEN TRY_CAST(puntuacion AS DOUBLE) END) AS a1,
           avg(CASE WHEN p_codmes = '202508' THEN TRY_CAST(puntuacion AS DOUBLE) END) AS b1,
